/* ==========================================
   RESET & BASE STYLES WITH BACKGROUND
   ========================================== */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html, body {
    width: 100%;
    overflow-x: hidden;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    color: #0f172a;
    line-height: 1.5;
    min-height: 100vh;
    display: flex;
    flex-direction: column;

    /* ФОНОВОЕ ИЗОБРАЖЕНИЕ С ОВЕРЛЕЕМ */
    background: 
        linear-gradient(135deg, rgba(248, 250, 252, 0.92), rgba(241, 245, 249, 0.88)),
        url('https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1920&q=80') center/cover no-repeat fixed;
}

#app {
    display: flex;
    flex-direction: column;
    min-height: 100vh;
    width: 100%;
}

/* ==========================================
   1. HEADER & NAVIGATION
   ========================================== */
header {
    background-color: rgba(15, 23, 42, 0.95);
