    --badge-cleaning-fg:    #1F5551;
    --badge-montage-bg:     #DFE9DD;
    --badge-montage-fg:     #2F5A32;

    /* --- Type --- */
    --font-display: 'Playfair Display', Georgia, 'Times New Roman', serif;
    --font-sans: 'Manrope', -apple-system, BlinkMacSystemFont, 'Segoe UI',
