import io, glob, sys

BS = chr(92)          # backslash, kept out of literals so no escaping games
SQ = chr(39)          # '
DQ = chr(34)          # "
BT = chr(96)          # `

def scan(src):
    """Walk the source once, skipping strings/templates/comments, balancing delimiters."""
    opens = {'{': 0, '(': 0, '[': 0}
    close = {'}': '{', ')': '(', ']': '['}
    match = {'{': '}', '(': ')', '[': ']'}
    i, n, line = 0, len(src), 1
    errs = []
    while i < n:
        c = src[i]
        if c == '\n':
            line += 1; i += 1; continue
        if c == '/' and i + 1 < n and src[i + 1] == '/':
            while i < n and src[i] != '\n':
                i += 1
            continue
        if c == '/' and i + 1 < n and src[i + 1] == '*':
            i += 2
            while i + 1 < n and not (src[i] == '*' and src[i + 1] == '/'):
                if src[i] == '\n':
                    line += 1
                i += 1
            i += 2; continue
        if c == SQ or c == DQ:
            q = c; start = line; i += 1
            while i < n and src[i] != q:
                if src[i] == BS:
                    i += 1
                elif src[i] == '\n':
                    errs.append((start, 'unterminated string')); break
                i += 1
            i += 1; continue
        if c == BT:
            i += 1
            while i < n and src[i] != BT:
                if src[i] == BS:
                    i += 1
                elif src[i] == '\n':
                    line += 1
                i += 1
            i += 1; continue
        if c in opens:
            opens[c] += 1
        elif c in close:
            opens[close[c]] -= 1
            if opens[close[c]] < 0:
                errs.append((line, 'extra ' + c))
        i += 1
    for k, v in opens.items():
        if v != 0:
            errs.append((0, 'unbalanced %s%s: %+d' % (k, match[k], v)))
    return errs

bad = 0
for f in sorted(glob.glob('js/**/*.js', recursive=True)):
    src = io.open(f, encoding='utf-8').read()
    e = scan(src)
    print(('  OK    ' if not e else '  FAIL  ') + f + ('' if not e else '  ' + str(e[:3])))
    if e:
        bad += 1
print('')
print('%d file(s) with problems' % bad)
sys.exit(1 if bad else 0)

