89	        if (res.ok) {
90	            const text = formatPhoton(await res.json());
91	            if (text) return text;
92	        }
93	    } catch (err) {
94	        // both providers unreachable
95	    }
96	
97	    return '';
98	}
99	
100	export function createLocationPicker(options) {
101	    const { mapEl, statusEl, buttonEl, addressInput, latInput, lngInput, strings, lang } = options;
102	
103	    let map = null;
104	    let marker = null;
105	    let lookupToken = 0;
106	    let destroyed = false;
107	
108	    function setStatus(text) {
109	        if (statusEl) statusEl.textContent = text;
110	    }
111	
112	    function writeCoords(lat, lng) {
113	        if (latInput) latInput.value = lat.toFixed(6);
114	        if (lngInput) lngInput.value = lng.toFixed(6);
115	    }
116	
117	    // Every lookup carries a token; a slow response from an older pin position
118	    // is discarded rather than overwriting a newer one.
119	    async function lookup(lat, lng) {
120	        const token = ++lookupToken;
121	        setStatus(strings.mapLocating);
122	        const text = await reverseGeocode(lat, lng, lang);
123	        if (destroyed || token !== lookupToken) return;
124	
125	        if (text) {
126	            if (addressInput) addressInput.value = text;
127	            setStatus(text);
128	        } else {
129	            setStatus(`${lat.toFixed(5)}, ${lng.toFixed(5)}`);
130	        }
131	    }
132	
133	    function placePin(L, lat, lng, zoom) {
134	        if (!map) return;
135	
136	        if (!marker) {
137	            marker = L.marker([lat, lng], {
138	                draggable: true,
139	                keyboard: true,
140	                icon: L.divIcon({
141	                    className: 'map-pin',
142	                    html: '<span class="map-pin-dot"></span>',
143	                    iconSize: [26, 26],
144	                    iconAnchor: [13, 26]
145	                })
146	            }).addTo(map);
147	
148	            marker.on('dragend', () => {
149	                const p = marker.getLatLng();
150	                writeCoords(p.lat, p.lng);
151	                lookup(p.lat, p.lng);
152	            });
153	        } else {
154	            marker.setLatLng([lat, lng]);
155	        }
156	
157	        map.setView([lat, lng], zoom || map.getZoom());
158	        writeCoords(lat, lng);
159	        lookup(lat, lng);
160	    }
161	
162	    function locate(L, userInitiated) {
163	        if (!navigator.geolocation) {
164	            setStatus(strings.mapDenied);
165	            return;
166	        }
167	
168	        // Geolocation only works in a secure context. On plain http (other than
169	        // localhost) the browser rejects it silently, so say so rather than
170	        // leaving the visitor waiting.
171	        if (!window.isSecureContext) {
172	            setStatus(strings.mapInsecure);
173	            return;
174	        }
175	
176	        setStatus(strings.mapLocating);
177	        navigator.geolocation.getCurrentPosition(
178	            (pos) => {
179	                if (destroyed) return;
180	                placePin(L, pos.coords.latitude, pos.coords.longitude, LOCATED_ZOOM);
181	            },
182	            () => {
183	                if (destroyed) return;
184	                setStatus(userInitiated ? strings.mapDenied : strings.mapHint);
185	            },
186	            { enableHighAccuracy: true, timeout: 10000, maximumAge: 60000 }
187	        );
188	    }
189	
190	    loadLeaflet().then((L) => {
191	        if (destroyed || !mapEl) return;
192	
193	        map = L.map(mapEl, {
194	            center: NEUTRAL_CENTER,
195	            zoom: NEUTRAL_ZOOM,
196	            scrollWheelZoom: false, // don't hijack the page scroll
197	            attributionControl: true
198	        });
199	
200	        L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png', {
201	            maxZoom: 19,
202	            attribution: '&copy; OpenStreetMap'
203	        }).addTo(map);
204	
205	        map.on('click', (e) => placePin(L, e.latlng.lat, e.latlng.lng));
206	
207	        if (buttonEl) {
208	            buttonEl.addEventListener('click', () => locate(L, true));
209	        }
210	
211	        // Deliberately no permission prompt on load - the browser only asks
212	        // when the visitor presses "Use my location".
213	        setStatus(strings.mapHint);
214	    }).catch(() => {
215	        setStatus(strings.mapUnavailable);
216	    });
217	
218	    return {
219	        destroy() {
220	            destroyed = true;
221	            if (map) {
222	                map.remove();
223	                map = null;
224	            }
225	            marker = null;
226	        }
227	    };
228	}

