"""Render a Claude Code .jsonl session into a readable Markdown transcript.

Keeps the human/assistant conversation and a one-line note per tool call, and
drops the bulky payloads (file snapshots, full tool output) that make the raw
JSONL unreadable. The raw files ship alongside for anyone who wants everything.
"""
import json
import sys
import io
import os


def text_blocks(content):
    """Content is either a plain string or a list of typed blocks."""
    if isinstance(content, str):
        return [("text", content)]
    out = []
    if isinstance(content, list):
        for b in content:
            if not isinstance(b, dict):
                continue
            t = b.get("type")
            if t == "text" and b.get("text", "").strip():
                out.append(("text", b["text"]))
            elif t == "thinking":
                pass  # internal reasoning, not part of the handover
            elif t == "tool_use":
                out.append(("tool", b.get("name", "tool")))
            elif t == "tool_result":
                out.append(("result", ""))
            elif t == "image":
                out.append(("image", ""))
    return out


def render(src, dst, title):
    turns = []
    with io.open(src, encoding="utf-8", errors="replace") as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            try:
                d = json.loads(line)
            except Exception:
                continue
            if d.get("type") not in ("user", "assistant"):
                continue
            msg = d.get("message") or {}
            role = msg.get("role") or d.get("type")
            blocks = text_blocks(msg.get("content"))
            if not blocks:
                continue
            turns.append((role, blocks))

    out = io.open(dst, "w", encoding="utf-8", newline="\n")
    out.write("# %s\n\n" % title)
    out.write("Readable export of the Claude Code session. Internal reasoning and\n")
    out.write("bulk tool output are omitted; tool calls appear as one-line notes.\n")
    out.write("The complete raw logs are in `raw/`.\n\n---\n\n")

    n_user = n_asst = n_tool = 0
    pending_tools = []

    def flush_tools():
        nonlocal pending_tools
        if pending_tools:
            uniq = []
            for t in pending_tools:
                if not uniq or uniq[-1][0] != t:
                    uniq.append([t, 1])
                else:
                    uniq[-1][1] += 1
            parts = ["%s%s" % (t, ("x%d" % c) if c > 1 else "") for t, c in uniq]
            out.write("> _(ran: %s)_\n\n" % ", ".join(parts))
            pending_tools = []

    for role, blocks in turns:
        texts = [v for k, v in blocks if k == "text"]
        tools = [v for k, v in blocks if k == "tool"]
        images = [1 for k, v in blocks if k == "image"]

        if tools:
            pending_tools.extend(tools)
            n_tool += len(tools)

        if not texts and not images:
            continue

        body = "\n\n".join(t.strip() for t in texts if t.strip())
        # skip the system-injected reminder blobs
        if body.startswith("<system-reminder>") or body.startswith("Caveat:"):
            continue

        if role == "user":
            flush_tools()
            n_user += 1
            out.write("## User\n\n")
            if images:
                out.write("_(%d image attachment%s)_\n\n" % (len(images), "" if len(images) == 1 else "s"))
            if body:
                out.write(body + "\n\n")
        else:
            n_asst += 1
            flush_tools()
            out.write("### Claude\n\n")
            if body:
                out.write(body + "\n\n")

    flush_tools()
    out.close()
    return n_user, n_asst, n_tool


if __name__ == "__main__":
    src, dst, title = sys.argv[1], sys.argv[2], sys.argv[3]
    u, a, t = render(src, dst, title)
    print("  %-46s %3d user / %3d assistant / %3d tool calls  (%.0f KB)"
          % (os.path.basename(dst), u, a, t, os.path.getsize(dst) / 1024.0))

